def R(code, name, short, pop, pcrel, dev, unrest, auto, reg, tr, sec, infra, edu, health, env, mix, desc, E, Ecal=None):
    return dict(code=code, name=name, short=short, pop=pop, pcrel=pcrel, dev=dev, unrest=unrest, auto=auto, reg=reg, tr=tr,
                sec={"ind": sec[0], "agr": sec[1], "srv": sec[2], "res": sec[3]}, infra=infra, edu=edu, health=health, env=env, mix=mix, desc=desc, E=E, Ecal=Ecal)


# 2019 год, общенациональный округ (%, оценка по областям ЦИК, округлено). ОПЗЖ делим между нынешними группами: «Платформа за жизнь и мир» ≈ 1/2,
# «Восстановление Украины» ≈ 0,3 (вместе с 0,3 «Оппозиционного блока»), остальное — «прочие»; «Довира» — доля самовыдвиженцев-мажоритарщиков.
def E19(sn, es, bat, gol, opzzh, ob, oth, zm, dov):
    pzm = opzzh * 0.5
    vu = opzzh * 0.3 + ob * 0.3
    rest = opzzh * 0.2 + ob * 0.7 + oth
    return [sn, es, bat, gol, pzm, vu, rest, zm, dov, 0.0]


def Ecal(row, vet):
    """для калибровки: доли 2019 года + региональный профиль ветеранских/«военных» списков (оценка по опросам 2025 года)"""
    r = list(row); r[9] = vet
    return r


